def money(amount): return f'{amount:,}'.replace(',', '.') + ' ₫'
def badge(kind, label):
    symbols = {'info':'◷','progress':'↻','success':'✓','warning':'!','danger':'!','neutral':'×'}
    return f'<span class="badge {kind}"><span aria-hidden="true">{symbols[kind]}</span> {label}</span>'
def card(p):
    return f'''<article class="product-card" data-name="{p['name']}" data-group="{p['group']}" data-price="{p['price']}">
    <a class="product-image" href="product.html?item={p['id']}" tabindex="-1" aria-hidden="true"><img src="../assets/{p['image']}.svg" alt="" width="600" height="480" loading="lazy"></a>
    <div class="product-copy"><p class="eyebrow">{p['category']}</p><h3><a href="product.html?item={p['id']}">{p['name']}</a></h3><p class="muted">{p['note']}</p><div class="price-line"><strong>{money(p['price'])}</strong><span aria-hidden="true">＋</span></div></div></article>'''

