def header(k, page):
    t = THEMES[k]
    role = 'ADMIN' if page == 'dashboard.html' else 'CUSTOMER' if page in ['vaccination.html','product.html'] else 'Khách'
    nav = ''.join(f'<a href="{file}"'+(' aria-current="page"' if page==file else '')+f'>{label}</a>' for file,label in PAGES)
    brand = '<svg class="brand-mark" viewBox="0 0 40 40" aria-hidden="true"><ellipse cx="20" cy="27" rx="12" ry="10"/><ellipse cx="7" cy="15" rx="5" ry="6"/><ellipse cx="17" cy="8" rx="5" ry="6"/><ellipse cx="29" cy="10" rx="5" ry="6"/><ellipse cx="35" cy="21" rx="4" ry="5"/></svg>'
    return f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{dict(PAGES)[page]} · {t['name']} · PetCare Hub</title><meta name="description" content="Bản xem trước giao diện PetCare Hub với dữ liệu minh họa tiếng Việt."><link rel="stylesheet" href="styles.css"><script src="../preview.js" defer></script></head>
    <body class="option-{k}"><a class="skip" href="#main">Bỏ qua menu, tới nội dung</a><div class="preview-bar"><div class="container"><span>Bản xem trước {k.upper()} · <a href="../index.html">So sánh 3 hướng</a></span><nav class="preview-links" aria-label="Chuyển trang bản xem trước">{nav}</nav></div></div>
    <header class="site-header"><nav class="container site-nav" aria-label="Menu chính"><a class="brand" href="index.html">{brand}PetCare Hub</a><div class="site-links"><a href="catalog.html">Khám phá sản phẩm</a><a href="catalog.html?group=SERVICE">Dịch vụ chăm sóc</a>{'<a href="vaccination.html">Thú cưng của tôi</a>' if role=='CUSTOMER' else ''}{'<a href="dashboard.html">Tổng quan quản trị</a>' if role=='ADMIN' else ''}<span class="role">{role} · mẫu</span></div></nav></header>'''

def footer():
    return '<footer class="footer"><div class="container"><span><strong>PetCare Hub</strong> · Chăm sóc bằng cả trái tim.</span><span>Dữ liệu minh họa · Không tạo giao dịch thật · <a href="../index.html">Đổi hướng thiết kế</a></span></div></footer></body></html>'

def home(k):
    t = THEMES[k]
    return f'''<main id="main" class="container"><section class="hero"><div class="hero-copy"><p class="eyebrow">{t['kicker']}</p><h1>{t['hero']}</h1><p class="lead muted">{t['lead']}</p><div class="actions"><a class="btn" href="catalog.html">Khám phá cửa hàng</a><a class="btn secondary" href="catalog.html?group=SERVICE">Tìm dịch vụ chăm sóc</a></div><p class="hero-note">Đồng hành từ những điều nhỏ nhất, mỗi ngày.</p></div><div class="hero-art"><img src="../assets/friends.svg" alt="Minh họa chú chó và mèo ngồi cạnh nhau" width="600" height="480"><div class="art-note"><strong>Một chút quan tâm</strong><span>Một ngày thật vui</span></div></div></section>
    <div class="benefits"><div><strong>Chọn điều phù hợp</strong><span class="muted">Thú cưng, phụ kiện và dịch vụ</span></div><div><strong>Chăm sóc có kế hoạch</strong><span class="muted">Theo dõi lịch hẹn và tiêm phòng</span></div><div><strong>Gắn bó thêm quyền lợi</strong><span class="muted">Thành viên và gói chăm sóc</span></div></div>
    <section class="section"><div class="section-title"><div><p class="eyebrow">Những điều nhỏ, niềm vui lớn</p><h2>Cho một ngày thật dễ thương</h2></div><a href="catalog.html">Xem tất cả sản phẩm</a></div><div class="product-grid">{''.join(card(p) for p in PRODUCTS[:3])}</div></section>
    <section class="section feature-panel"><div><p class="eyebrow">Góc chăm sóc</p><h2>Mỗi lịch hẹn, một sự quan tâm.</h2><p>Theo dõi những mốc chăm sóc để không bỏ lỡ điều quan trọng.</p></div><a class="btn" href="catalog.html?group=SERVICE">Khám phá dịch vụ</a></section>
    <section class="section"><div class="section-title"><div><h2>Khám phá các màn hình mẫu</h2><p class="muted">Chuyển bối cảnh để so sánh giao diện khách hàng và quản trị.</p></div></div><div class="actions"><a class="btn secondary" href="product.html">Chi tiết sản phẩm</a><a class="btn secondary" href="vaccination.html">Hồ sơ tiêm phòng · CUSTOMER</a><a class="btn secondary" href="dashboard.html">Dashboard · ADMIN</a></div></section></main>'''

def catalog():
    return f'''<main id="main" class="container"><nav class="breadcrumb" aria-label="Đường dẫn"><a href="index.html">Trang chủ</a><span>/ Cửa hàng</span></nav><div class="page-title"><p class="eyebrow">Dành cho người bạn nhỏ</p><h1>Một chút yêu thương, mỗi ngày.</h1><p class="muted">Tìm phụ kiện, dịch vụ và người bạn phù hợp với cuộc sống của bạn.</p></div><div class="catalog-layout"><form class="filters" id="filters"><h2>Tìm điều bạn cần</h2><div class="field"><label for="q">Tên sản phẩm</label><input id="q" name="q" type="search" placeholder="Ví dụ: đai dắt"></div><div class="field"><label for="group">Nhóm sản phẩm</label><select id="group" name="group"><option value="">Tất cả nhóm</option><option value="PET">Thú cưng</option><option value="ACCESSORY">Phụ kiện</option><option value="SERVICE">Dịch vụ / gói</option></select></div><div class="field"><label for="sort">Sắp xếp theo giá</label><select id="sort" name="sort"><option value="asc">Giá tăng dần</option><option value="desc">Giá giảm dần</option></select></div><div class="actions"><button class="btn" type="submit">Áp dụng lọc</button><button class="btn secondary" type="reset">Đặt lại</button></div></form><section aria-label="Kết quả sản phẩm"><div class="result-summary"><strong id="result-count" role="status" aria-live="polite">6 sản phẩm mẫu</strong><span>Giá tham khảo</span></div><noscript><p class="notice">Bật JavaScript để dùng bộ lọc. Bạn vẫn có thể xem các sản phẩm bên dưới.</p></noscript><div class="product-grid" id="product-grid">{''.join(card(p) for p in PRODUCTS)}</div><p id="empty" class="empty" hidden>Không có sản phẩm phù hợp. Hãy thử từ khóa khác hoặc chọn “Đặt lại”.</p></section></div></main>'''

def product():
    p = PRODUCTS[0]
    return f'''<main id="main" class="container"><nav class="breadcrumb" aria-label="Đường dẫn"><a href="index.html">Trang chủ</a><span>/</span><a href="catalog.html">Cửa hàng</a><span>/ Chi tiết sản phẩm</span></nav><section class="detail-grid"><div class="detail-art"><img id="detail-image" src="../assets/harness.svg" alt="Minh họa đai dắt màu xanh lá" width="600" height="480"></div><div class="detail-copy"><p class="eyebrow" id="detail-category">Phụ kiện</p>{badge('success','Đang có sẵn · mẫu')}<h1 id="detail-name">{p['name']}</h1><p class="muted" id="detail-description">{p['description']}</p><p class="price" id="detail-price">{money(p['price'])}</p><p id="detail-spec">{p['spec']}</p><hr><form id="demo-purchase"><div class="field" id="quantity-field"><label for="quantity">Số lượng</label><input id="quantity" name="quantity" type="number" min="1" max="9" value="1" required></div><button class="btn" id="purchase-button" type="submit">Thử thêm vào giỏ</button></form><p id="purchase-feedback" role="status" aria-live="polite" class="notice" hidden></p><p class="hero-note">Tương tác minh họa, không đặt hàng hoặc đặt lịch thật.</p><noscript><p class="notice">JavaScript đang tắt: đang hiển thị đai dắt mẫu. Bật JavaScript để xem đúng sản phẩm đã chọn và thử tương tác.</p></noscript></div></section><section class="section detail-notes"><div class="panel"><h2>Chọn phù hợp với bé</h2><p>Đọc kỹ thông tin, kích thước và nhu cầu chăm sóc trước khi lựa chọn. Thông số trong bản xem trước chỉ là dữ liệu minh họa.</p><a href="catalog.html">Tiếp tục khám phá cửa hàng</a></div><div class="panel"><h2>Chăm sóc trọn vẹn hơn</h2><p>Giữ các mốc tiêm phòng và lịch sử chăm sóc ở cùng một nơi, để mỗi lần ghé cửa hàng đều thuận tiện.</p><a href="vaccination.html">Xem hồ sơ tiêm phòng mẫu của Bông</a></div></section></main>'''

def vaccination():
    records = [('COMPLETED','success','Đã tiêm','Mũi tiêm mẫu 01','05/10/2026','Đã xác nhận tiêm ngày 05/10/2026.','2026-10-05'),('OVERDUE','danger','Quá hạn','Mũi tiêm mẫu 02','12/11/2026','Quá hạn 7 ngày so với ngày tham chiếu.','2026-11-12'),('DUE_SOON','warning','Sắp đến hạn','Mũi tiêm mẫu 03','23/11/2026','Còn 4 ngày đến lịch hẹn.','2026-11-23'),('SCHEDULED','info','Đã lên lịch','Mũi tiêm mẫu 04','15/12/2026','Đã ghi nhận lịch hẹn tiếp theo.','2026-12-15')]
    timeline = ''.join(f'<li data-state="{state}"><article class="panel"><div class="timeline-heading"><h3>{name}</h3>{badge(kind,label)}</div><p>Ngày hẹn: <time datetime="{iso}">{date}</time></p><p class="muted">{note}</p></article></li>' for state,kind,label,name,date,note,iso in records)
